with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'الاستشعار الفضائي والرادار وتقنيات الرصد المتقدمة','رادار دوبلر وثنائي الاستقطاب ومنتجات الهطول واسترجاعات الأقمار ومتجهات الحركة والبرق وتقنيات GNSS والليدار ورصد الطائرات والبحر.',23,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الرادار المتقدم ومنتجات الهطول',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الأقمار الصناعية والاسترجاع المتقدم',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u3 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'تقنيات الرصد المتقدمة',3,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('doppler-weather-radar-principles','رادار دوبلر للطقس ومبادئ قياس الحركة','المسح الحجمي والسرعة الشعاعية وأنماط الدوران والقيود الهندسية.','{"blocks":[{"type":"text","text":"يقيس رادار دوبلر تغير تردد الإشارة المرتدة لتقدير مركبة حركة الهدف على خط النظر إلى الرادار."},{"type":"text","text":"تختلف السرعة الشعاعية عن سرعة الرياح الكاملة؛ فهي تمثل الإسقاط على اتجاه شعاع الرادار."},{"type":"text","text":"تستخدم الانعكاسية لتقدير شدة الإشارة المرتدة من الهيدروميتورات، بينما تستخدم السرعة الشعاعية لدراسة الحركة."},{"type":"text","text":"تنتج عمليات المسح الحجمي قطوعاً متعددة الارتفاعات لتكوين تصور ثلاثي الأبعاد للعاصفة."},{"type":"text","text":"تساعد أنماط السرعة المتقابلة على تحديد مناطق دوران أو قص داخل العواصف، مع مراعاة زاوية المسح ودقة الشعاع."},{"type":"text","text":"قد يؤدي الطي السرعي velocity aliasing إلى ظهور قيم سرعة غير صحيحة إذا تجاوزت السرعة حد نايكويست."},{"type":"text","text":"تؤثر المسافة عن الرادار وارتفاع الشعاع وانحناء الأرض في الجزء الجوي الذي يمكن رصده."},{"type":"text","text":"قد تظهر أهداف غير جوية مثل التضاريس والطيور والحشرات، وتحتاج إلى مرشحات جودة مناسبة."},{"type":"text","text":"تؤثر دورة المسح وسرعة دوران الهوائي في التوازن بين التغطية الزمنية والدقة الرأسية."},{"type":"text","text":"تستخدم بيانات الرادار مع السبر والمحطات والأقمار لتفسير بنية العاصفة."},{"type":"text","text":"مثال: وجود دوران في السرعة الشعاعية يحتاج فحص عدة زوايا ومسوح متتابعة قبل تفسيره كدوران مستمر."},{"type":"callout","text":"خلاصة: رادار دوبلر يوفر معلومات حركية مهمة، لكنه يقيس مركبة شعاعية ضمن هندسة محددة."}]}',1560,60,'["شرح مبدأ دوبلر","تمييز الانعكاسية عن السرعة","فهم حدود الرصد الشعاعي"]','الرادار المتقدم ومنتجات الهطول'),
('dual-polarization-weather-radar','الرادار ثنائي الاستقطاب والمنتجات الهيدروميتورية','الانعكاسية التفاضلية ونسبة التباين والطور التفاضلي وتصنيف الهطول.','{"blocks":[{"type":"text","text":"يرسل الرادار ثنائي الاستقطاب ويستقبل موجات مستقطبة أفقياً وعمودياً لتوفير معلومات إضافية عن شكل وحجم واتجاه الأهداف."},{"type":"text","text":"تصف الانعكاسية التفاضلية ZDR الفرق بين الانعكاسية الأفقية والعمودية، وقد تساعد في تمييز شكل الجسيمات."},{"type":"text","text":"تعبر نسبة التباين أو معامل الارتباط rhoHV عن تشابه خصائص الإشارات الأفقية والعمودية من الأهداف داخل حجم الرصد."},{"type":"text","text":"يساعد الطور التفاضلي المحدد KDP على تقييم بعض خصائص الهطول، ويستخدم في تقدير المطر في ظروف مناسبة."},{"type":"text","text":"تستخدم المنتجات القطبية مجتمعة لتصنيف أنواع الهيدروميتورات مثل المطر والثلج والبرد والمزيج."},{"type":"text","text":"قد تشير قيم غير معتادة إلى أهداف غير جوية أو تلوث أو اضطراب في الإشارة، ويجب فحص الجودة قبل التصنيف."},{"type":"text","text":"تختلف استجابة المنتجات بحسب نوع الهطول ودرجة الحرارة وحجم الجسيمات وشكلها واتجاهها."},{"type":"text","text":"تحتاج خوارزميات تصنيف الهيدروميتورات إلى معايرة محلية ومقارنة ببيانات أرضية وسبر جوي."},{"type":"text","text":"قد تتحسن تقديرات المطر في بعض الظروف عند استخدام KDP وZDR بدلاً من الانعكاسية وحدها."},{"type":"text","text":"لا تعد منتجات الرادار الثنائي قياساً مباشراً لكل حبة أو قطرة، بل استدلالاً من خصائص الإشارة المجمعة."},{"type":"text","text":"مثال: ارتفاع ZDR مع انعكاسية مناسبة قد يتوافق مع قطرات مطر كبيرة مفلطحة، لكن التفسير يحتاج سياقاً متكاملاً."},{"type":"callout","text":"خلاصة: الاستقطاب المزدوج يضيف معلومات نوعية عن الهيدروميتورات ويحسن بعض منتجات الهطول."}]}',1570,60,'["شرح الاستقطاب المزدوج","التعرف إلى المنتجات القطبية","فهم تصنيف الهيدروميتورات"]','الرادار المتقدم ومنتجات الهطول'),
('radar-quantitative-precipitation-estimation','التقدير الكمي للهطول باستخدام الرادار','تحويل الانعكاسية والمنتجات القطبية إلى تقديرات مطر ومراعاة الانحياز.','{"blocks":[{"type":"text","text":"يهدف التقدير الكمي للهطول QPE إلى تقدير كمية المطر الهاطلة مكانياً وزمنياً باستخدام بيانات الرادار ومصادر مساعدة."},{"type":"text","text":"تستخدم علاقات تجريبية تربط الانعكاسية Z بمعدل المطر R، وتختلف معاملات العلاقة بحسب نوع الهطول والمنطقة."},{"type":"text","text":"قد تكون العلاقة التقليدية Z-R غير مناسبة عند تغير حجم القطرات أو وجود الثلج والبرد أو الهطول المختلط."},{"type":"text","text":"تساعد منتجات الاستقطاب المزدوج في تحسين تقدير المطر عبر معلومات إضافية عن خصائص الهيدروميتورات."},{"type":"text","text":"يتأثر QPE بالتوهين والحجب الأرضي والارتفاع المتزايد للشعاع وتغير حجم العينة مع المسافة."},{"type":"text","text":"قد يؤدي انصهار الثلج في طبقة الذوبان إلى نطاق انعكاسية مرتفع لا يعكس معدل المطر السطحي مباشرة."},{"type":"text","text":"تستخدم مقاييس المطر الأرضية لمعايرة تقديرات الرادار والتحقق منها، مع مراعاة تمثيل المقياس النقطي مقابل الشبكي."},{"type":"text","text":"تتطلب المقارنة مطابقة زمنية ومكانية بين تراكم الرادار وقياس المحطة."},{"type":"text","text":"تستخدم خوارزميات دمج المحطات والرادار لتقليل بعض الانحيازات وتحسين التغطية."},{"type":"text","text":"ينبغي توثيق فترة التجميع والدقة المكانية ومصدر المنتج ونسبة التغطية."},{"type":"text","text":"مثال: مقارنة تراكم الرادار خلال ساعة بمقياس مطر تتطلب التأكد من تطابق بداية ونهاية الفترة الزمنية."},{"type":"callout","text":"خلاصة: QPE منتج مقدر يحتاج معايرة محلية وفهماً لمصادر الخطأ وعدم اليقين."}]}',1580,60,'["شرح تقدير المطر من الرادار","فهم علاقات Z-R","تقييم مصادر الخطأ"]','الرادار المتقدم ومنتجات الهطول'),
('satellite-cloud-microphysics-retrievals','استرجاع الخصائص الدقيقة للسحب من الأقمار','تقدير حجم القطرات والطور والماء السائل وخصائص قمم السحب.','{"blocks":[{"type":"text","text":"تسترجع الأقمار الصناعية بعض خصائص السحب من قياسات الإشعاع في قنوات مرئية وتحت حمراء وقريبة من تحت الحمراء."},{"type":"text","text":"تشمل المنتجات المحتملة نصف قطر قطرات السحب البصري والطور ودرجة حرارة القمة والضغط وعمق الماء السائل."},{"type":"text","text":"تستجيب القنوات المختلفة لأعماق وأجزاء مختلفة من السحابة، لذلك تعتمد النتيجة على نموذج الاسترجاع."},{"type":"text","text":"قد يساعد الجمع بين قنوات مرئية وتحت حمراء في التمييز بين السحب المائية والجليدية والمختلطة."},{"type":"text","text":"تتأثر المنتجات بزاوية الشمس والرصد والسطح أسفل السحب والغيوم المتعددة الطبقات."},{"type":"text","text":"قد تكون الاسترجاعات أقل موثوقية ليلاً أو فوق أسطح معقدة أو في حالات السحب الرقيقة."},{"type":"text","text":"تختلف دقة المنتج المكاني والزمني بحسب القمر والمستشعر ونمط المسح."},{"type":"text","text":"تستخدم القياسات الأرضية والرادار والليدار للتحقق من بعض خصائص السحب المسترجعة."},{"type":"text","text":"لا تمثل قيمة الاسترجاع قياساً مباشراً داخل كل نقطة من السحابة، بل تقديراً يعتمد على افتراضات فيزيائية."},{"type":"text","text":"ينبغي قراءة أعلام الجودة والقيود قبل استخدام المنتج في التحليل أو التحقق."},{"type":"text","text":"مثال: قد يساعد تغير نصف قطر القطرات في تتبع تطور السحب، لكن يجب تفسيره مع طور السحابة وعمقها وبيئتها."},{"type":"callout","text":"خلاصة: منتجات الميكروفيزياء الفضائية توفر رؤية واسعة لكنها تعتمد على افتراضات الاسترجاع وجودة الإشارة."}]}',1590,60,'["تمييز القياس عن الاسترجاع","فهم الخصائص الميكروفيزيائية","التعرف إلى قيود القنوات"]','الأقمار الصناعية والاسترجاع المتقدم'),
('atmospheric-motion-vectors-from-satellites','متجهات الحركة الجوية المستنتجة من الأقمار','تتبع السحب وبخار الماء لاشتقاق اتجاه الرياح وسرعتها.','{"blocks":[{"type":"text","text":"تستنتج متجهات الحركة الجوية AMV من تتبع أنماط السحب أو بخار الماء في صور أقمار متتابعة."},{"type":"text","text":"يقاس انتقال سمة مرئية أو طيفية بين صور زمنية، ثم يحول الإزاحة إلى سرعة واتجاه وفق زمن التصوير والهندسة."},{"type":"text","text":"يعد تحديد ارتفاع السمة خطوة مهمة لأن المتجه يجب أن يرتبط بمستوى جوي مناسب."},{"type":"text","text":"تستخدم درجات حرارة السحب أو معلومات القنوات الطيفية أو ملفات الحرارة لتقدير مستوى الارتفاع."},{"type":"text","text":"قد تنشأ أخطاء إذا تغير شكل السحابة أو تلاشت أو نمت بين الصور بدلاً من انتقالها فقط."},{"type":"text","text":"تختلف جودة المتجهات باختلاف نوع السمة والغطاء السحابي وزمن التكرار والدقة المكانية."},{"type":"text","text":"تستخدم اختبارات الاتساق مع الخلفية والنماذج والمحطات لاستبعاد بعض المتجهات منخفضة الجودة."},{"type":"text","text":"توفر الأقمار الثابتة تغطية متكررة مناسبة لتتبع السحب، بينما توفر أقمار أخرى أنماط تغطية مختلفة."},{"type":"text","text":"تدخل متجهات الحركة في بعض أنظمة استيعاب البيانات لتحسين تقدير الرياح."},{"type":"text","text":"يجب معرفة ارتفاع المتجه ووقت الرصد ومؤشر الجودة قبل استخدامه في التحليل."},{"type":"text","text":"مثال: تتبع سحب عالية يعطي تقديراً لرياح الطبقات العليا، وليس بالضرورة للرياح القريبة من السطح."},{"type":"callout","text":"خلاصة: متجهات الأقمار تضيف تغطية رياح واسعة، لكن جودة الارتفاع والتتبع أساسية."}]}',1600,60,'["شرح مبدأ تتبع السمات","فهم تحديد الارتفاع","تقييم جودة متجهات الرياح"]','الأقمار الصناعية والاسترجاع المتقدم'),
('satellite-lightning-observation','رصد البرق من الأقمار الصناعية','المستشعرات البصرية المدارية ومراقبة الومضات وتطور العواصف.','{"blocks":[{"type":"text","text":"تستخدم بعض الأقمار مستشعرات بصرية لرصد الومضات الضوئية المرتبطة بالتفريغات الكهربائية في العواصف."},{"type":"text","text":"توفر مستشعرات البرق الفضائية تغطية واسعة لمناطق قد لا تغطيها شبكات البرق الأرضية."},{"type":"text","text":"قد تقيس المنتجات عدد الومضات أو الأحداث أو المجموعات وفق تعريف المستشعر وخوارزمية المعالجة."},{"type":"text","text":"تختلف الومضة البصرية عن ضربة البرق الأرضية؛ فقد تضم الومضة عدة تفريغات أو أحداثاً داخل السحابة."},{"type":"text","text":"تساعد معدلات الوميض وتغيرها زمنياً في متابعة تطور النشاط الكهربائي للعواصف."},{"type":"text","text":"تتأثر المشاهدات بالسحب والضوء الخلفي ودقة المستشعر ومجال الرؤية والتمييز بين الإشارة والضوضاء."},{"type":"text","text":"تحتاج مقارنة بيانات الأقمار بشبكات البرق الأرضية إلى فهم اختلاف تعريف الحدث والتغطية والحساسية."},{"type":"text","text":"تستخدم بيانات البرق مع الرادار والأقمار متعددة الأطياف لتقييم نشاط الحمل العميق."},{"type":"text","text":"قد تظهر فروق زمنية ومكانية بين المستشعر الفضائي والرادار بسبب اختلاف حجم العينة ومعدل التحديث."},{"type":"text","text":"ينبغي توثيق نوع المنتج ووحدة العد والفترة الزمنية عند إعداد خرائط البرق."},{"type":"text","text":"مثال: ارتفاع عدد الومضات خلال عدة مسوح قد يشير إلى زيادة النشاط الكهربائي، ويجب فحص تطور السحابة والرادار أيضاً."},{"type":"callout","text":"خلاصة: رصد البرق الفضائي يضيف تغطية واسعة ومعلومة زمنية مهمة لتشخيص العواصف."}]}',1610,60,'["شرح رصد البرق الفضائي","تمييز الومضة عن التفريغ الأرضي","فهم حدود التغطية"]','الأقمار الصناعية والاسترجاع المتقدم'),
('gnss-meteorology-and-precipitable-water','الأرصاد باستخدام GNSS والماء القابل للترسيب','استخدام تأخير إشارات الملاحة الفضائية لتقدير بخار الماء الجوي.','{"blocks":[{"type":"text","text":"تتأثر إشارات أنظمة الملاحة بالأقمار الصناعية بالغلاف الجوي أثناء انتقالها إلى المستقبل الأرضي."},{"type":"text","text":"يسهم بخار الماء في التأخير الرطب للإشارة، ويمكن استخدامه لتقدير كمية بخار الماء في العمود الجوي."},{"type":"text","text":"يستخرج التأخير الرطب بعد فصل المكونات الهندسية والجافة باستخدام نماذج ومعلومات مساعدة."},{"type":"text","text":"يمكن تحويل التأخير الرطب إلى ماء قابل للترسيب PWV باستخدام معلومات الحرارة المتوسطة للغلاف الجوي."},{"type":"text","text":"يمثل PWV عمق الماء المكافئ إذا تكاثف كل بخار الماء في العمود الهوائي."},{"type":"text","text":"تتيح شبكات مستقبلات GNSS رصداً مستمراً نسبياً يمكن أن يكمل الراديوسوند والأقمار."},{"type":"text","text":"تتأثر جودة التقدير بتوزيع المستقبلات ومعايرة الهوائي والظروف المحلية ونمذجة التأخير."},{"type":"text","text":"قد يساعد التغير السريع في PWV على متابعة تراكم الرطوبة قبل بعض أحداث الهطول، لكنه لا يحدد المطر وحده."},{"type":"text","text":"تستخدم بيانات GNSS في بعض أنظمة استيعاب البيانات لتحسين تحليل الرطوبة."},{"type":"text","text":"تحتاج المقارنة مع الراديوسوند والقياسات الفضائية إلى مطابقة زمنية ومكانية ومراعاة اختلاف حجم العينة."},{"type":"text","text":"مثال: ارتفاع PWV مع تقارب الرياح والرفع قد يشير إلى بيئة رطبة ملائمة للهطول عند توافر آليات أخرى."},{"type":"callout","text":"خلاصة: GNSS مصدر رصد مستمر للرطوبة العمودية ويدعم التحليل والتنبؤ قصير المدى."}]}',1620,60,'["شرح تأخير الإشارة في الغلاف الجوي","فهم الماء القابل للترسيب","التعرف إلى تطبيقات GNSS"]','تقنيات الرصد المتقدمة'),
('lidar-ceilometer-and-wind-profiler','الليدار ومقاييس قاعدة السحب ومقاييس الرياح الرأسية','الاستشعار النشط للهباء والسحب والرياح في المقاطع الرأسية.','{"blocks":[{"type":"text","text":"الليدار يستخدم نبضات ضوئية لقياس التشتت والانعكاس من الجسيمات والسحب في الغلاف الجوي."},{"type":"text","text":"يستخدم مقياس قاعدة السحب Ceilometer لتقدير ارتفاع قواعد السحب من زمن عودة الإشارة الضوئية."},{"type":"text","text":"تساعد ملفات الليدار في رصد طبقات الهباء وارتفاع طبقة الخلط وبعض خصائص السحب الرقيقة."},{"type":"text","text":"تستخدم مقاييس الرياح الرأسية Wind Profilers موجات راديوية أو تقنيات أخرى لتقدير الرياح على مستويات متعددة."},{"type":"text","text":"يختلف الليدار عن الرادار في نوع الموجة والتفاعل مع الجسيمات والمدى والحساسية للظروف الجوية."},{"type":"text","text":"قد تتأثر أجهزة الليدار بالهطول الكثيف والضباب الكثيف والتوهين البصري، بينما تتأثر أجهزة الرادار بعوامل أخرى."},{"type":"text","text":"تساعد مقارنة الملفات الرأسية بالمحطات والسبر والأقمار على التحقق من ارتفاع الطبقات والسحب."},{"type":"text","text":"تستخدم بعض الأنظمة تأثير دوبلر في الليدار لتقدير مركبة حركة الهواء على خط النظر."},{"type":"text","text":"تحتاج القياسات إلى ضبط المعايرة والمحاذاة وتوثيق نوع الجهاز وارتفاعه وموقعه."},{"type":"text","text":"تدعم هذه الأجهزة مراقبة المطارات والطبقة الحدية وجودة الهواء والظواهر الرأسية."},{"type":"text","text":"مثال: تغير ارتفاع طبقة الخلط خلال النهار يمكن تتبعه بمنتجات الليدار وقياسات الحرارة والرياح."},{"type":"callout","text":"خلاصة: أدوات الاستشعار النشط تكمل الرصد التقليدي بتفاصيل رأسية مستمرة."}]}',1630,60,'["تمييز الليدار عن الرادار","شرح قياس قاعدة السحب","فهم ملفات الرياح الرأسية"]','تقنيات الرصد المتقدمة'),
('aircraft-observations-and-amdar','رصد الطائرات وبيانات AMDAR','استخدام قياسات الطائرات التجارية لتحسين تغطية الحرارة والرياح والرطوبة.','{"blocks":[{"type":"text","text":"توفر الطائرات التجارية قياسات جوية أثناء الصعود والهبوط وعلى مستويات الطيران."},{"type":"text","text":"يشير AMDAR إلى نظام تبادل بيانات أرصاد الطائرات آلياً وفق مواصفات تشغيلية."},{"type":"text","text":"تشمل القياسات الشائعة درجة الحرارة والرياح، وقد تتوفر الرطوبة في بعض الأساطيل أو البرامج."},{"type":"text","text":"تقدم قياسات الإقلاع والهبوط ملفات رأسية قرب المطارات، بينما توفر الرحلات المستوية معلومات على مستويات الطيران."},{"type":"text","text":"تختلف كثافة البيانات مكانياً وزمانياً بحسب مسارات الرحلات والجداول وشبكات المطارات."},{"type":"text","text":"تحتاج بيانات الطائرات إلى معايرة الحساسات ومراعاة أثر هيكل الطائرة وسرعتها وارتفاعها."},{"type":"text","text":"قد تكون التغطية أقل فوق المحيطات والمناطق ذات الحركة الجوية المحدودة."},{"type":"text","text":"تستخدم بيانات الطائرات في استيعاب البيانات والتحقق من توقعات الرياح والحرارة."},{"type":"text","text":"يجب توثيق نوع الطائرة ووقت القياس والارتفاع والخصائص المتاحة لتفسير السجل."},{"type":"text","text":"تعد بيانات الطائرات مكملة للراديوسوند والأقمار والمحطات وليست بديلاً شاملاً عنها."},{"type":"text","text":"مثال: قياسات متتابعة أثناء الهبوط قد توفر ملفاً حرارياً ورياحياً مفيداً للتحقق من التنبؤ قرب المطار."},{"type":"callout","text":"خلاصة: رصد الطائرات يزيد كثافة القياسات في مسارات الطيران ويدعم التحليل العددي."}]}',1640,60,'["شرح بيانات AMDAR","فهم خصائص رصد الطائرات","تقييم تمثيل المسارات الجوية"]','تقنيات الرصد المتقدمة'),
('ocean-buoys-scatterometers-altimeters','العوامات البحرية ومقاييس التشتت وارتفاع سطح البحر','الرصد البحري السطحي والرياح المستنتجة من الأقمار وقياس ارتفاع البحر.','{"blocks":[{"type":"text","text":"توفر العوامات البحرية قياسات مباشرة للرياح والضغط وحرارة الهواء وسطح البحر والأمواج وفق تجهيز المحطة."},{"type":"text","text":"تثبت بعض العوامات في مواقع محددة، بينما تنجرف أخرى مع التيارات وتوفر مسارات زمنية للمحيط."},{"type":"text","text":"تستخدم مقاييس التشتت الفضائية الإشارة الميكروية المرتدة من سطح البحر لاستنتاج خصائص الرياح السطحية فوق المحيط."},{"type":"text","text":"تتأثر استرجاعات الرياح بحالة البحر والأمطار والاتجاه وسرعة الرياح ونموذج المعالجة."},{"type":"text","text":"تستخدم مقاييس الارتفاع الرادارية لقياس المسافة إلى سطح البحر واستنتاج ارتفاعه بالنسبة إلى مرجع مداري."},{"type":"text","text":"تسهم قياسات ارتفاع سطح البحر في دراسة الأمواج والمد والتيارات والتغيرات المحيطية طويلة الأمد بعد تطبيق التصحيحات اللازمة."},{"type":"text","text":"تحتاج بيانات الأقمار إلى تصحيحات مدارية وجوية ومدية وجيوفيزيائية بحسب نوع المنتج."},{"type":"text","text":"تساعد مقارنة العوامات والمنتجات الفضائية على تقييم الانحياز والتغطية والاختلاف المكاني."},{"type":"text","text":"قد تختلف دقة المنتجات قرب السواحل بسبب انعكاس اليابسة وتغير خصائص السطح."},{"type":"text","text":"تستخدم البيانات البحرية في التنبؤ الجوي والمحيطي وتحليل الأعاصير والأنظمة الساحلية."},{"type":"text","text":"مثال: دمج قياسات عوامة مع رياح القمر الصناعي يساعد في تقييم مجال الرياح فوق منطقة بحرية واسعة."},{"type":"callout","text":"خلاصة: تكامل العوامات والأقمار يوفر رصداً بحرياً مباشراً وواسع التغطية."}]}',1650,60,'["شرح مصادر الرصد البحري","فهم مقياس التشتت","التعرف إلى قياس ارتفاع سطح البحر"]','تقنيات الرصد المتقدمة'))
insert into public.academy_lessons(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,case d.unit when 'الرادار المتقدم ومنتجات الهطول' then u1.id when 'الأقمار الصناعية والاسترجاع المتقدم' then u2.id when 'تقنيات الرصد المتقدمة' then u3.id end,d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'advanced',d.mins,d.objectives::jsonb,'الاستشعار الفضائي والرادار وتقنيات الرصد المتقدمة',d.unit from d cross join c cross join ch cross join u1 cross join u2 cross join u3
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;